<script lang="ts">import '$lib/design/tokens.css'; import '$lib/components/commerce/store.css'; import { rankProducts, type AdvisorAnswers, type SmartProduct, type SkillLevel } from '$lib/smart-shopping'; import type { PageData } from './$types'; let { data }: { data: PageData } = $props(); let group = $state<AdvisorAnswers['group']>('machine'); let skill = $state<SkillLevel | ''>(''); let style = $state(''); let submitted = $state(false); let results = $derived(submitted ? rankProducts((data.products as any[]).map(p => ({ id:p.id,name:p.name,slug:p.slug,smart:p.inkora_smart })) as SmartProduct[], { group, skill: skill || undefined, style: style || undefined }) : []);</script>
<svelte:head><title>راهنمای انتخاب تجهیزات | اینکورا</title><meta name="description" content="پیشنهاد شفاف بر پایهٔ متادیتای واقعی محصولات موجود." /></svelte:head>
<div class="inkora-theme inkora-store smart-page" dir="rtl"><header class="store-header"><div class="store-container store-header-inner"><a class="store-brand" href="/"><img src="/assets/brand/inkora-wordmark-temporary.svg" alt="اینکورا؛ نوشتار موقت برند" /></a><nav class="store-nav" aria-label="ناوبری"><a href="/shop">فروشگاه</a><a href="/advisor" aria-current="page">انتخاب‌گر</a><a href="/compare">مقایسه</a><a href="/simulator">شبیه‌ساز</a></nav></div></header><main class="store-container store-main"><p class="eyebrow">دادهٔ واقعی، قاعدهٔ روشن</p><h1>راهنمای انتخاب تجهیزات</h1><p class="lead">این ابزار فقط کالاهای منتشرشده، موجود و دارای متادیتای کامل را بررسی می‌کند؛ هیچ توصیه‌ای را حدس نمی‌زند.</p>{#if data.status === 'error'}<section class="empty-copy" role="alert"><h2>دادهٔ فروشگاه در دسترس نیست</h2><p>اتصال WooCommerce را بررسی کنید.</p></section>{:else if !data.products.length}<section class="smart-panel"><h2>هنوز دادهٔ کافی برای پیشنهاد وجود ندارد</h2><p>مدیر: در ویرایش یک کالای واقعی و موجود، تب «Inkora smart shopping» را پر کنید: گروه، سطح، سبک‌ها و مشخصات فنی لازم. کالای تست داخلی هرگز وارد این ابزار نمی‌شود.</p><a class="button" href="/shop">بازگشت به فروشگاه</a></section>{:else}<form class="smart-panel advisor-form" onsubmit={(e) => { e.preventDefault(); submitted = true; }}><fieldset><legend>۱. دنبال چه گروهی هستید؟</legend><label><input type="radio" bind:group value="machine" /> دستگاه</label><label><input type="radio" bind:group value="needle" /> سوزن یا کارتریج</label><label><input type="radio" bind:group value="ink" /> رنگ</label></fieldset><label for="skill">۲. سطح مهارت (اختیاری)</label><select id="skill" bind:value={skill}><option value="">بدون فیلتر</option><option value="beginner">مبتدی</option><option value="intermediate">میانی</option><option value="professional">حرفه‌ای</option></select><label for="style">۳. سبک (اختیاری)</label><select id="style" bind:value={style}><option value="">بدون فیلتر</option><option value="linework">لاین‌ورک</option><option value="shading">سایه‌زنی</option><option value="color">رنگی</option><option value="blackwork">بلک‌ورک</option><option value="realism">رئالیسم</option><option value="traditional">ترادیشنال</option></select><button class="button primary" type="submit">نمایش تطبیق‌های مستند</button></form>{#if submitted}<section class="smart-results" aria-live="polite"><h2>خلاصهٔ پاسخ‌ها</h2><p>گروه: {group} · سطح: {skill || 'بدون فیلتر'} · سبک: {style || 'بدون فیلتر'}</p><p class="empty-copy">رتبه‌بندی: ۲ امتیاز برای سطح یکسان و ۱ امتیاز برای ثبت سبک انتخاب‌شده. فقط نتیجه با دست‌کم یک تطبیق نشان داده می‌شود.</p>{#if results.length}<ol>{#each results as result}<li><a href={`/shop/${result.product.slug}`}>{result.product.name}</a> — {result.reasons.join('؛ ')}</li>{/each}</ol>{:else}<p class="smart-panel">هیچ تطبیق مستندی پیدا نشد. این به‌معنای نامناسب‌بودن کالا نیست؛ دادهٔ لازم وارد نشده یا کالا موجود نیست.</p>{/if}</section>{/if}{/if}</main></div>
